    /// One of: FaceOut, BodyOut.
    enum FaceOutOrBodyOut: Codable, Hashable, Sendable {
        case faceOut(FaceOut)
        case bodyOut(BodyOut)

        init(from decoder: Decoder) throws {
            let keys = try decoder.container(keyedBy: AnyKey.self)
            if keys.contains(AnyKey("quality")) && keys.contains(AnyKey("size_px")) {
                self = .faceOut(try FaceOut(from: decoder))
                return
            }
            if let value = try? BodyOut(from: decoder) {
                self = .bodyOut(value)
                return
            }
            throw DecodingError.dataCorrupted(DecodingError.Context(
                codingPath: decoder.codingPath, debugDescription: "None of FaceOut, BodyOut"))
        }

        func encode(to encoder: Encoder) throws {
            switch self {
            case .faceOut(let value): try value.encode(to: encoder)
            case .bodyOut(let value): try value.encode(to: encoder)
            }
        }
    }

